void printInfo() {
  Serial.println("\n=== ИНФОРМАЦИЯ О ПЛАТЕ ===");
  Serial.printf("Модель чипа: %s\n", ESP.getChipModel());
  Serial.printf("Ревизия: %d\n", ESP.getChipRevision());
  Serial.printf("Частота CPU: %d MHz\n", ESP.getCpuFreqMHz());
  Serial.printf("Размер Flash: %d MB\n", ESP.getFlashChipSize() / (1024 * 1024));
  Serial.printf("Свободная память (Heap): %d байт\n", ESP.getFreeHeap());

  uint64_t chipid = ESP.getEfuseMac();
  Serial.printf("MAC-адрес: %04X%08X\n", (uint16_t)(chipid >> 32), (uint32_t)chipid);
  Serial.println("==========================");
}

void setup() {
  Serial.begin(115200);
  delay(3000); // Ждем 3 секунды, чтобы ты успел открыть монитор порта
  printInfo();
}

void loop() {
  // Повторяем вывод каждые 3 секунды, чтобы ты точно увидел данные
  printInfo(); 
  delay(3000);
}
